style.css:
@-moz-document domain("kapybara.okoun.cz") {
body, header.board-header
 {
        background: #000!important;
 }

header.?-header
 {
        background: #1c1816!important;
        border-bottom: 1px solid #444
 }

.?-stripes 
 {
  background: none !important;
 }

header.post-header
 {
        border-bottom: 1px solid #777 !important;
        border-top: 1px solid #777 !important;
        margin-top: 2px !important;
        margin-bottom: 0px !important;
        padding-top: 3px !important;
        height: 24px !important;
        background: #24282b!important;
 }

div.post-main > div.body-wrap > div.body.?-content
 {
        margin-top: 15px !important;
 }

.post.unread.read
 {
        background: #171b1d!important;
        border-left: 4px solid #d4892a !important;
        border-bottom-left-radius: 9px !important;
        border-top-left-radius: 0px !important;
        border-top-right-radius: 0px !important;
        border-bottom-right-radius: 0px !important;
        border-right: 2px solid #d4892a !important;
        margin-bottom: -12px !important;
 }

.post.unread
 {
        background: #202224!important;
        border-left: 4px solid #4f8cbe !important;
        border-bottom-left-radius: 9px !important;
        border-top-left-radius: 0px !important;
        border-top-right-radius: 0px !important;
        border-bottom-right-radius: 0px !important;
        border-right: 2px solid #4f8cbe !important;
        margin-bottom: -12px !important;
 }
 
.post
 {
        margin-bottom: -16px !important;
 }

.post.unread:before
 {
        background: #161819!important;
 }

div.post-main > h2 
 {
        margin-top: 5px !important;
        margin-left: 45px !important;
        font-size: 120% !important;
        margin-bottom: -10px !important;
        color: #fff !important;
 }

article.post
 {
        background: #000!important;
 }

article.separator-above
 {
        margin-top: -10px !important;
 }

button.date
 {
        border-bottom: none !important;
 }

div.composer-entry, section.new-post-composer
 {
        background: #181b1e!important;
        border: 1px solid #666
 }

input.?-field-control, span.?-float-label, div.composer
 {
       background: #111!important;
 }

span.avatar
 {
       border-radius: 0% !important;
       box-shadow: 0 0 0 1px #666 !important;
 }

button.avatar-button
 {
       border: 1px solid #123!important;
 }

a.row:visited > div > div > div > span.name, div.body> div> p> a:visited, div.body-wrap> div.body > a:visited, div.html-body > a:visited, a.okoun-embed__link:visited, div.markdown > p > a:visited
 {
       color: #f94!important;
 }

a.row:hover > div > div > div > span.name, a:hover, a.row:hover > div > div > div > span.name, div.body> div> p> a:hover, div.body-wrap> div.body > a:hover, div.html-body > a:hover, button.reply-action:hover
 {
       color: #fc3!important;
 }

button.reply-action:hover
 {
        border: 1px solid #666 !important;
 }

button.reply-action
 {
        border: 1px solid #66666630 !important;
        margin-bottom: 4px !important;
 }

nav.nav-links > a:hover
 {
       text-decoration: underline !important;
       color: #fc3!important;
 }

li > a.row > div.content:hover, li > a.row:hover
 {
       background-color: #151515!important;

 }

li > a.row:hover
 {
       border-top: 1px solid #444!important;
       border-bottom: 1px solid #444!important;
 }

li > a.row
 {
       border-top: 1px solid #000!important;
       border-bottom: 1px solid #000!important;
 }

section.favorites-page > div.alert-gap > div.alert.info 
 {
       border-top: 1px solid #444!important;
       background-color: #161616 !important;
       color: #aaa  !important;
       border-bottom: 1px solid #444!important;
 }

div.edge-bleed > div.topics > details.topic > summary 
 {
        display: none !important;
 }

span.?-new-pill
 {
        color: #eee !important;
        background-color: #2d2622 !important;
        border-color: #666 !important;
        border-radius: 8px !important;
 }

span.more-toggle:hover
 {
       color: #fc3!important;
       text-decoration: underline!important;
 }

div.row-with-icon > div.content-col > a.row
 {
       border-top: 1px solid #6660!important;
       border-bottom: 1px solid #6660!important;
 }

div.row-with-icon > div.content-col > a.row:hover
 {
       background-color: #161616!important;
       border-top: 1px solid #444!important;
       border-bottom: 1px solid #444!important;
 }

div.welcome-box
 {
       border-top: 1px solid #666!important;
       border-bottom: 1px solid #666!important;
       border-left: 1px solid #4440!important;
       border-right: 1px solid #4440!important;
 }

span.muted-inline-excerpt
 {
        display: none !important;
 }

button.muted-expand
 {
       background-color: #161616!important;
       border: 1px solid #444 !important;
       padding: 0px!important;
       padding-right: 12px !important;
       padding-left: 8px !important;
       color: #a37200!important;
       box-shadow: none !important;
       margin-top: 5px !important;
       margin-right: 15px !important;
       border-radius: 8px !important;
       float: right !important;
 }

button.muted-expand:hover
 {
       background-color: #222!important;
       border: 1px solid #888 !important;
       color: #d7a500!important;
       text-decoration: underline !important;
 }

 .post.muted
 {
        opacity: 1 !important;
 }

article.muted > div.avatar-col, article.muted > div.post-main > header
 {
        opacity: .4!important;
        filter: saturate(0);
 }

div.welcome-box
 {
        background: #151519!important;
 }

button.pin-icon
 {
		      color: #777!important;
		      display: inline-block!important;
		      flex: none!important;
		      margin: 0px!important;
		      padding: 0px!important;
		      margin-top: 12px!important;
	      	margin-left: -30px!important;
	     	 z-index: 1!important;
		      width: 1px!important;
		      height: 1px!important;
 }

button.pin-icon > svg:hover
 {
        color: #d7a500!important;
 }

button.pin-icon > svg
 {
        color: #999!important;
 }

span.rating-badge.explicit
 {
        color: #ccc!important;
        background-color: #300!important;
        border: 1px solid #b20!important;
		      border-radius: 8px!important;
 }
 
span.rating-badge.sensitive
 {
        color: #ccc!important;
        background-color: #332b00!important;
        border: 1px solid #bb9f00!important;
		      border-radius: 8px!important;
 }

span.spoiler
 {
        border: 1px solid  #666!important;
 }

 span.spoiler.revealed
 {
        border: 1px solid  #666!important;
        background-color: #323232 !important;
 }
 
div.actions > button.?-button.?-button--contained.?-button--primary.?-button--medium, div.pane-header > button.new-message-button, div.composer-actions > button.?-button.?-button--contained.?-button--primary.?-button--medium
 {
        border: 1px solid  #9b670e!important;
        background-color: #9b670e !important;
 }
   
div.actions > button.?-button.?-button--contained.?-button--primary.?-button--medium:hover,div.pane-header > button.new-message-button:hover, div.composer-actions > button.?-button.?-button--contained.?-button--primary.?-button--medium:hover
 {
        border: 1px solid #eba500!important;
        background-color: #eba500!important;
 }
 
div.actions > button.?-button.?-button--contained.?-button--primary.?-button--medium:disabled, div.composer-actions > button.?-button.?-button--contained.?-button--primary.?-button--medium:disabled
 {
        border: 1px solid  #666!important;
        background-color: #323232 !important;
 }
 
 div.collapsed-composer-shell > button.collapsed-send
 {
        opacity: 1!important;
        border: 1px solid  #666!important;
        background-color: #323232 !important;
        color: #666!important;
 }
 
 div.composer-entry > button.entry-prispet
 {
        background: #555 !important;
        color: #ccc !important;
        border: 1px solid #555!important;
 }

div.composer-entry > button.entry-prispet:hover
 {
        background: #eba500!important;
        color: #000 !important;
        border: 1px solid #eba500!important;
 }
 
 
 article.unread.muted.read
 {
        border-left: 6px solid #9999996e !important;
        border-right: 2px solid #9999996e !important;
        background: #1618196e!important;
 }
 
 article.muted > div > div > div > div.html-body
 {
        opacity: .4!important;
 } 
 
 article.muted > div > div > div > span > div.reply-preview
 {
        border: 4px solid  #fff3!important;
        background-color: #151515f5 !important;
 }
 
  article.muted > div > div > div > span > div.reply-preview > div.reply-preview-body > div.html-body, article.muted > div > div > div > span > div.reply-preview > div.reply-preview-meta > strong, article.muted > div > div > div > span > div.reply-preview > div.reply-preview-body > div.markdown
 {
         color: #ffffff96 !important;
 }
 
 div.reply-preview
 {
        border: 4px solid  #497e8d5e!important;
        background-color: #181d21f5 !important;
 }
 
 .body.?-trfpop .okoun-embed
 {
 max-width: min(100%,1024px);
 }
 
 pre
  {
   white-space: pre-wrap;
  overflow-wrap: break-word;
  }
 
 div.?-shell
 {
 max-width: 1200px;
 }
 
